async ({ shell: { execFile } }) => {
  const m = await execFile("gh", ["pr", "merge", "74", "--squash", "--delete-branch"]);
  const notes: Record<string, string> = {};
  for (const n of ["61", "62", "70", "72", "73", "71", "74"]) {
    const v = await execFile("gh", ["pr", "view", n, "--json", "title,body"]);
    const j = JSON.parse(v.stdout);
    const i = j.body.search(/## Release note/i);
    notes[n] = j.title + "\n" + (i >= 0 ? j.body.slice(i, i + 2500) : "(no release note) " + j.body.slice(0, 400));
  }
  return { merge: m.code + " " + m.stdout + m.stderr, notes };
}
